import{j as e,bZ as n}from"./vendor-BIIlzuAX.js";import{b as t}from"./index-BLutTH3J.js";import{f as i}from"./format-tool-output-DsVJGnBx.js";import{A as a}from"./AIToolPage-BAl72HD6.js";import"./vendor-react-DZP9pdoc.js";import"./vendor-charts-D6Ioj7zX.js";import"./ai-Db3qOlMd.js";import"./WorksheetRenderer-BEpDqNr-.js";import"./send-data-C012DnLw.js";import"./pdf-generator-v2-CG2Ni7tf.js";import"./FunFactsCarousel-CPuszUCJ.js";import"./docx-export-qRWFMNtA.js";const s=["English","Maths","Science","History","Geography","RE","PSHE","Art","Music","PE","Computing","MFL","Design Technology","Drama","Citizenship","Business Studies","Economics","Psychology","Sociology","Law","Media Studies","Film Studies","Physical Education","Health & Social Care"].map(e=>({value:e,label:e})),o=["Reception","Year 1","Year 2","Year 3","Year 4","Year 5","Year 6","Year 7","Year 8","Year 9","Year 10","Year 11","Year 12","Year 13"].map(e=>({value:e,label:e})),r=["20 minutes","30 minutes","45 minutes","50 minutes","60 minutes","75 minutes","90 minutes","100 minutes"].map(e=>({value:e,label:e}));function l(){const{preferences:l}=t();return e.jsx(a,{title:"Lesson Plan Generator",assignable:!0,worksheetLink:!0,description:"Generate detailed, SEND-inclusive, curriculum-aligned lesson plans ready to teach",icon:e.jsx(n,{className:"w-5 h-5 text-white"}),accentColor:"bg-blue-600",fields:[{id:"subject",label:"Subject",type:"select",options:s,required:!0,span:"half"},{id:"yearGroup",label:"Year Group",type:"select",options:o,required:!0,span:"half"},{id:"topic",label:"Topic / Learning Focus",type:"text",placeholder:"e.g. Fractions, The Water Cycle, WW2 Causes",required:!0,span:"full"},{id:"duration",label:"Lesson Duration",type:"select",options:r,span:"half"},{id:"classSize",label:"Class Size",type:"text",placeholder:"e.g. 28 pupils",span:"half"},{id:"sendNeeds",label:"SEND / Additional Needs",type:"text",placeholder:"e.g. 3 pupils with dyslexia, 2 with ADHD, 1 EAL",span:"full"},{id:"priorLearning",label:"Prior Learning / Starting Point",type:"textarea",placeholder:"What do pupils already know? What misconceptions might they have?",span:"full"},{id:"objectives",label:"Learning Objectives (optional — leave blank for AI to generate)",type:"textarea",placeholder:"e.g. Students will be able to explain the causes of WW2",span:"full"},{id:"resources",label:"Available Resources",type:"text",placeholder:"e.g. iPads, mini whiteboards, manipulatives, textbooks",span:"full"},{id:"examBoard",label:"Exam Board (if applicable)",type:"text",placeholder:"e.g. AQA, Edexcel, OCR, WJEC",span:"half"},{id:"teachingStyle",label:"Teaching Approach",type:"select",options:[{value:"direct",label:"Direct Instruction"},{value:"inquiry",label:"Inquiry-Based Learning"},{value:"collaborative",label:"Collaborative / Group Work"},{value:"flipped",label:"Flipped Classroom"},{value:"mixed",label:"Mixed / Blended"}],span:"half"}],buildPrompt:e=>({system:"You are an outstanding, award-winning UK teacher with 15+ years of experience and expertise in SEND-inclusive pedagogy, curriculum design, and evidence-based teaching. You have deep knowledge of the UK National Curriculum, Ofsted inspection framework, and best practices from the Education Endowment Foundation (EEF). You write lesson plans that are detailed, practical, and immediately ready to deliver — a supply teacher with no subject knowledge should be able to pick this up and teach it confidently.\n\nYour lesson plans are distinguished by:\n- Precise, measurable learning objectives aligned to curriculum standards\n- Expertly structured pedagogy using Rosenshine's Principles, retrieval practice, and spaced learning\n- Genuine, meaningful SEND adaptations (not tokenistic)\n- Engaging, age-appropriate activities that build deep understanding\n- Built-in assessment for learning throughout every phase\n- Professional, publication-quality formatting",user:`Create a comprehensive, professional-grade lesson plan with the following details:\n\n**Subject:** ${e.subject}\n**Year Group:** ${e.yearGroup}\n**Topic:** ${e.topic}\n**Duration:** ${e.duration||"60 minutes"}\n**Class Size:** ${e.classSize||"Mixed ability class"}\n**SEND / Additional Needs:** ${e.sendNeeds||"Mixed ability — standard differentiation required"}\n**Prior Learning:** ${e.priorLearning||"Standard prior knowledge for this year group and topic"}\n**Teaching Approach:** ${e.teachingStyle||"Mixed / Blended"}\n${e.objectives?`**Specified Learning Objectives:** ${e.objectives}`:""}\n${e.resources?`**Available Resources:** ${e.resources}`:""}\n${e.examBoard?`**Exam Board:** ${e.examBoard}`:""}\n\nPlease produce a fully detailed lesson plan with ALL of the following sections:\n\n## LESSON OVERVIEW\n- Subject, Year Group, Topic, Duration, Date (leave blank)\n- NC/Curriculum reference (specific programme of study link)\n- Lesson number in unit (e.g. Lesson 3 of 6)\n\n## LEARNING OBJECTIVES\nThree tiered objectives:\n- **Must** (all pupils): Core knowledge/skill every pupil will achieve\n- **Should** (most pupils): Expected progress for the majority\n- **Could** (some pupils): Challenge/extension for higher attainers\n\n## SUCCESS CRITERIA\nPupil-friendly "I can..." statements (3–5 statements) that pupils can self-assess against\n\n## KEY VOCABULARY\nTable with 6–10 key words, their definitions, and example usage in context\n\n## RESOURCES REQUIRED\nComplete list of everything needed (including any preparation required)\n\n## LESSON STRUCTURE\n\n### STARTER / HOOK (${Math.round(.12*parseInt(e.duration||"60"))} minutes)\nEngaging retrieval/activation activity — specific instructions, questions to ask, expected pupil responses\n\n### MAIN TEACHING — EXPLICIT INSTRUCTION (${Math.round(.25*parseInt(e.duration||"60"))} minutes)\nStep-by-step teacher explanation with:\n- Exact key points to cover\n- Worked examples to model\n- Common misconceptions to address\n- Questions to check understanding (include specific questions with expected answers)\n\n### GUIDED PRACTICE (${Math.round(.18*parseInt(e.duration||"60"))} minutes)\nTeacher-led activity with the class — specific task with instructions\n\n### INDEPENDENT PRACTICE (${Math.round(.3*parseInt(e.duration||"60"))} minutes)\nThree differentiated tasks:\n- **Support Task** (scaffolded): Specific task with sentence starters, word banks, or frames\n- **Core Task** (expected): Main independent activity\n- **Extension Task** (challenge): Higher-order thinking, application, or evaluation\n\n### PLENARY (${Math.round(.1*parseInt(e.duration||"60"))} minutes)\nConsolidation activity — specific exit ticket question or activity\n\n## SEND ADAPTATIONS\nFor each need mentioned, provide specific, practical strategies:\n- Seating arrangements\n- Scaffolding tools (word mats, sentence frames, visual supports)\n- Adult support deployment\n- Alternative recording methods\n- Sensory/environmental adjustments\n\n## ASSESSMENT FOR LEARNING\n- Formative assessment strategies used throughout (with specific timing)\n- Key questions to ask at each phase (include 2–3 specific questions)\n- Success indicators — what does good look like?\n- Next steps — how will this lesson inform the next?\n\n## HOMEWORK / FOLLOW-UP (optional)\nSpecific homework task with clear instructions\n\n## TEACHER NOTES\n- Potential misconceptions and how to address them\n- Subject knowledge notes for non-specialists\n- Links to prior and future learning\n\nFormat everything with clear markdown headers and be extremely specific and practical throughout. Every activity should have precise instructions, timings, and expected outcomes.`,maxTokens:4e3}),outputTitle:e=>`Lesson Plan: ${e.subject} — ${e.topic} (${e.yearGroup})`,formatOutput:e=>i(e,{logoUrl:l.schoolLogoUrl,schoolName:l.schoolName,accentColor:"#2563eb",emoji:"📋",title:"Lesson Plan"}),isLessonPlan:!0})}export{l as default};
